      {
        "id": "6590b3f2-be5c-3f6b-9b1f-727e75fa3bbb",
        "question": "Pernyataan mana sesuai kemampuan dan kesukaan Deni?",
        "question_type": "multiple_choice",
        "question_category": "listening",
        "section_number": 12,
        "section_label": "きいて わかること",
        "section_instruction": "こえを きいて、こたえて ください。\nDengarkan informasi yang diminta.",
        "passage": null,
        "audio_script": "N: アンナさんと デニさんの はなしです。\nA: アンナさんは にほんごが じょうずですね。\nB: はい。デニさんは にほんごが すきです。あまり じょうずじゃありません。\nN: デニさんは どうですか。",
        "image_url": null,
        "correct_answer": null,
        "explanation": "Audio menyebut Deni suka bahasa Jepang tetapi belum begitu mahir.",
        "sort_order": 34,
        "assessment_meta": {
          "version": "n5-assessment-v5",
          "form": "A",
          "key": "b07-a-expanded-listening-1",
          "objective": "goal3",
          "itemType": "key_points",
          "distractorReasons": [
            "Audio menyebut Deni suka bahasa Jepang tetapi belum begitu mahir.",
            "Sangat mahir adalah informasi tentang Anna; tidak berlaku untuk Deni.",
            "Audio menyebut Deni suka dan belum begitu mahir, bukan sebaliknya.",
            "Bagian tidak suka bertentangan dengan audio."
          ]
        },
        "options": [
          {
            "id": "1ac0c34d-c907-3617-854d-18125187ba2d",
            "option_text": "すきです。あまり じょうずじゃありません。",
            "is_correct": true,
            "sort_order": 1
          },
          {
            "id": "0a8a8a28-aa9a-389d-b462-9a84065ba9ce",
            "option_text": "すきで、とても じょうずです。",
            "is_correct": false,
            "sort_order": 2
          },
          {
            "id": "0a796ac9-826d-3f02-ad5c-242c07b6b0ee",
            "option_text": "きらいです。とても じょうずです。",
            "is_correct": false,
            "sort_order": 3
          },
          {
            "id": "59037a4b-3884-3dd2-8b7b-3fb6cbd4d7a2",
            "option_text": "きらいで、へたです。",
            "is_correct": false,
            "sort_order": 4
          }
        ]
      },
      {
        "id": "10cc5f30-0003-3443-8994-faeb6e59c045",
        "question": "こえを きいて、こたえて ください。",
        "question_type": "multiple_choice",
        "question_category": "listening",
        "section_number": 14,
        "section_label": "すぐに こたえる",
        "section_instruction": "こえを きいて、へんじを えらんで ください。こたえも こえで ききます。\nDengarkan ujaran dan tiga respons; pilih respons yang sesuai.",
        "passage": null,
        "audio_script": "A: これは どんな まちですか。\nN: いちばん。\nB: しずかで、きれいな まちです。\nN: にばん。\nB: まちは どこですか。\nN: さんばん。\nB: にほんごが じょうずです。",
        "image_url": null,
        "correct_answer": null,
        "explanation": "どんなまち meminta deskripsi kota; respons pertama menyebut tenang dan bersih/indah.",
        "sort_order": 35,
        "assessment_meta": {
          "version": "n5-assessment-v5",
          "form": "A",
          "key": "b07-a-expanded-listening-2",
          "objective": "goal2",
          "itemType": "quick_response",
          "distractorReasons": [
            "どんなまち meminta deskripsi kota; respons pertama menyebut tenang dan bersih/indah.",
            "Ini pertanyaan lokasi baru, bukan jawaban deskripsi kota.",
            "Kemahiran bahasa Jepang menggambarkan kemampuan seseorang, bukan sifat kota."
          ],
