        "question_category": "vocabulary",
        "section_number": 1,
        "section_label": "漢字の よみかた",
        "section_instruction": "ことばの よみかたを えらんで ください。<details><summary>Petunjuk</summary>Pilih bacaan kata bergaris bawah.</details>",
        "passage": null,
        "audio_script": null,
