        "question_category": "vocabulary",
        "section_number": 4,
        "section_label": "おなじ いみ",
        "section_instruction": "おなじ いみの ぶんを えらんで ください。<details><summary>Petunjuk</summary>Pilih ungkapan bermakna setara.</details>",
        "passage": null,
        "audio_script": null,
