      {
        "id": "56dce720-978d-3128-a442-a23f095b492e",
        "question": "こえを きいて、こたえて ください。",
        "question_type": "multiple_choice",
        "question_category": "listening",
        "section_number": 14,
        "section_label": "すぐに こたえる",
        "section_instruction": "こえを きいて、へんじを えらんで ください。こたえも こえで ききます。<details><summary>Petunjuk</summary>Dengarkan ujaran dan tiga respons; pilih respons yang sesuai.</details>",
        "passage": null,
        "audio_script": "A: きのう、テストの べんきょうを した？\nN: いちばん。\nB: ううん、しない。\nN: にばん。\nB: ううん、する。\nN: さんばん。\nB: ううん、しなかった。",
        "image_url": null,
        "correct_answer": null,
        "explanation": "Pertanyaan bentuk biasa lampau dijawab dengan negatif lampau しなかった.",
