]$plan$::jsonb;
 b jsonb; r jsonb; choice jsonb; target uuid; course uuid; matches int;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('curriculum-boundary:graph'));
 SELECT id INTO course FROM courses WHERE slug='n5';
 IF course IS NULL THEN RAISE EXCEPTION '216: N5 course missing'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('curriculum-boundary:'||course));
 LOCK TABLE lessons,quiz_questions,quiz_options IN SHARE ROW EXCLUSIVE MODE;
 -- Preflight every chapter before creating any new active bank.
 FOR b IN SELECT value FROM jsonb_array_elements(plan) LOOP
  SELECT count(*),(array_agg(l.id))[1] INTO matches,target
  FROM lessons l JOIN modules m ON m.id=l.module_id
  WHERE m.course_id=course AND m.slug='n5-b'||(b->>'chapter')
   AND l.type='quiz' AND l.slug LIKE 'assignment-bab-'||(b->>'chapter')||'-%';
  IF matches<>1 THEN RAISE EXCEPTION '216: missing/ambiguous Bab %',b->>'chapter'; END IF;
  IF EXISTS(SELECT 1 FROM n5_assessment_backup_216 WHERE lesson_id=target) THEN CONTINUE; END IF;
  IF (SELECT assessment_policy->>'version' FROM lessons WHERE id=target) IS DISTINCT FROM b->>'expectedVersion'
   THEN RAISE EXCEPTION '216: source version changed Bab %',b->>'chapter'; END IF;
  IF (SELECT count(*) FROM quiz_questions WHERE lesson_id=target AND assessment_meta->>'version'=b->>'expectedVersion')<>jsonb_array_length(b->'sources')
   THEN RAISE EXCEPTION '216: source count changed Bab %',b->>'chapter'; END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(b->'sources') LOOP
   IF NOT EXISTS(SELECT 1 FROM quiz_questions WHERE id=(r->>'id')::uuid AND lesson_id=target AND assessment_meta->>'version'=b->>'expectedVersion'
     AND assessment_meta->>'form'=r->>'form')
    THEN RAISE EXCEPTION '216: source identity changed Bab %',b->>'chapter'; END IF;
  END LOOP;
  IF (SELECT jsonb_typeof(assessment_policy->'objectives') FROM lessons WHERE id=target) IS DISTINCT FROM 'array'
   THEN RAISE EXCEPTION '216: missing objectives Bab %',b->>'chapter'; END IF;
  IF (SELECT count(*)=0 OR count(*)<>count(DISTINCT objective->>'id') OR count(*) FILTER(WHERE nullif(objective->>'id','') IS NULL)>0
   FROM lessons l CROSS JOIN LATERAL jsonb_array_elements(l.assessment_policy->'objectives') objective WHERE l.id=target)
   THEN RAISE EXCEPTION '216: invalid objectives Bab %',b->>'chapter'; END IF;
 END LOOP;
 FOR b IN SELECT value FROM jsonb_array_elements(plan) LOOP
  SELECT l.id INTO target FROM lessons l JOIN modules m ON m.id=l.module_id
   WHERE m.course_id=course AND m.slug='n5-b'||(b->>'chapter') AND l.type='quiz'
    AND l.slug LIKE 'assignment-bab-'||(b->>'chapter')||'-%';
  IF EXISTS(SELECT 1 FROM n5_assessment_backup_216 WHERE lesson_id=target) THEN CONTINUE; END IF;
  INSERT INTO n5_assessment_backup_216(lesson_id,before_lesson,before_questions)
   SELECT l.id,to_jsonb(l),coalesce((SELECT jsonb_agg(to_jsonb(q)||jsonb_build_object('options',
    (SELECT jsonb_agg(to_jsonb(o) ORDER BY o.sort_order,o.id) FROM quiz_options o WHERE o.question_id=q.id)) ORDER BY q.id)
    FROM quiz_questions q WHERE q.lesson_id=l.id AND q.assessment_meta->>'version'=b->>'expectedVersion'),'[]'::jsonb)
   FROM lessons l WHERE l.id=target;
  FOR r IN SELECT value FROM jsonb_array_elements(b->'clones') LOOP
   INSERT INTO quiz_questions(id,lesson_id,question,question_type,question_category,grammar_id,
    section_number,section_label,section_instruction,audio_script,audio_scene,passage,image_url,correct_answer,explanation,sort_order,assessment_meta)
   SELECT (r->>'id')::uuid,target,q.question,q.question_type,q.question_category,q.grammar_id,
    q.section_number,q.section_label,q.section_instruction,q.audio_script,q.audio_scene,q.passage,q.image_url,q.correct_answer,q.explanation,q.sort_order,
    q.assessment_meta||jsonb_build_object('version','n5-assessment-v5','key',r->>'key')
   FROM quiz_questions q WHERE q.id=(r->>'sourceId')::uuid;
   INSERT INTO quiz_options(id,question_id,option_text,is_correct,image_url,sort_order)
    SELECT md5(id::text||':n5-assessment-v5')::uuid,(r->>'id')::uuid,option_text,is_correct,image_url,sort_order
    FROM quiz_options WHERE question_id=(r->>'sourceId')::uuid;
  END LOOP;
  FOR r IN SELECT value FROM jsonb_array_elements(b->'additions') LOOP
   INSERT INTO quiz_questions(id,lesson_id,question,question_type,question_category,section_number,section_label,
    section_instruction,passage,audio_script,image_url,correct_answer,explanation,sort_order,assessment_meta)
   VALUES((r->>'id')::uuid,target,r->>'question',r->>'question_type',r->>'question_category',(r->>'section_number')::int,
    r->>'section_label',r->>'section_instruction',r->>'passage',r->>'audio_script',r->>'image_url',r->>'correct_answer',r->>'explanation',(r->>'sort_order')::int,r->'assessment_meta');
   FOR choice IN SELECT value FROM jsonb_array_elements(r->'options') LOOP
    INSERT INTO quiz_options(id,question_id,option_text,is_correct,sort_order)
     VALUES((choice->>'id')::uuid,(r->>'id')::uuid,choice->>'option_text',(choice->>'is_correct')::boolean,(choice->>'sort_order')::int);
   END LOOP;
  END LOOP;
  IF EXISTS(SELECT 1 FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5'
    AND ((SELECT count(*) FROM quiz_options o WHERE o.question_id=q.id)<>CASE WHEN q.assessment_meta->>'itemType' IN ('verbal_expression','quick_response') THEN 3 ELSE 4 END
     OR (SELECT count(*) FROM quiz_options o WHERE o.question_id=q.id AND is_correct)<>1))
   THEN RAISE EXCEPTION '216: invalid choices Bab %',b->>'chapter'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(b->'forms') AS forms(form) WHERE
    (SELECT count(*) FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5' AND assessment_meta->>'form'=forms.form)<>36
    OR (SELECT count(*) FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5' AND assessment_meta->>'form'=forms.form AND question_category='vocabulary')<>11
    OR (SELECT count(*) FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5' AND assessment_meta->>'form'=forms.form AND question_category='grammar')<>9
    OR (SELECT count(*) FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5' AND assessment_meta->>'form'=forms.form AND question_category='reading')<>3
    OR (SELECT count(*) FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5' AND assessment_meta->>'form'=forms.form AND question_category='listening')<>13)
   THEN RAISE EXCEPTION '216: invalid blueprint Bab %',b->>'chapter'; END IF;
  IF EXISTS(SELECT 1 FROM quiz_questions q WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v5'
   AND NOT EXISTS(SELECT 1 FROM lessons l CROSS JOIN LATERAL jsonb_array_elements(l.assessment_policy->'objectives') objective
    WHERE l.id=target AND objective->>'id'=q.assessment_meta->>'objective'))
   OR EXISTS(SELECT 1 FROM lessons l CROSS JOIN LATERAL jsonb_array_elements(l.assessment_policy->'objectives') objective
    CROSS JOIN jsonb_array_elements_text(b->'forms') AS forms(form) WHERE l.id=target
    AND NOT EXISTS(SELECT 1 FROM quiz_questions q WHERE q.lesson_id=target AND q.assessment_meta->>'version'='n5-assessment-v5'
     AND q.assessment_meta->>'form'=forms.form AND q.assessment_meta->>'objective'=objective->>'id'))
   THEN RAISE EXCEPTION '216: objective coverage changed Bab %',b->>'chapter'; END IF;
  UPDATE lessons SET assessment_policy=assessment_policy||'{"version":"n5-assessment-v5","questionsPerForm":36}'::jsonb,
   questions_per_attempt=36,
   content=replace(replace(content,'24 soal','36 soal'),'6 aksara dan kosakata, 10 tata bahasa, 4 membaca, dan 4 listening','11 aksara dan kosakata, 9 tata bahasa, 3 membaca, dan 13 listening'),
   updated_at=now() WHERE id=target;
  RAISE NOTICE '216: N5 Bab % active: 36 per packet (11 vocabulary, 9 grammar, 3 reading, 13 listening)',b->>'chapter';
 END LOOP;
END;
$expanded$;
